class VisionAcceleratorError(RuntimeError):
    pass


@contextlib.contextmanager
def numpy_operation():
    try:
        yield
    except MemoryError:
        raise
    except Exception as error:
        if is_memory_failure(error):
            raise
        raise VisionAcceleratorError("NumPy 视觉计算失败：" + str(error)) from error


def is_memory_failure(error):
    return (isinstance(error, MemoryError) or
            getattr(error, "winerror", None) in (WINERROR_NOT_ENOUGH_MEMORY, WINERROR_OUTOFMEMORY))


@functools.lru_cache(maxsize=VISION_GRID_CACHE_ENTRIES)
def numpy_sample_grid(numpy, width, height, stride):
    xs = numpy.arange(stride // 2, width, stride, dtype=numpy.int32)
    ys = numpy.arange(stride // 2, height, stride, dtype=numpy.int32)
    x, y = numpy.meshgrid(xs, ys)
    flat = (y * width + x).ravel()
    return x, y, flat


def is_stop_key(key, stop_key):
    return stop_key is not None and key in STOP_KEY_EQUIVALENTS.get(stop_key, (stop_key,))


def utc_stamp():
    return datetime.datetime.now(datetime.timezone.utc).isoformat()


def python_abi():
    tag = "cp" + str(sys.version_info.major) + str(sys.version_info.minor)
    return tag + ("t" if sysconfig.get_config_var("Py_GIL_DISABLED") else "")

